import XCTest
import ZIPFoundation
import RunPlayCore
@testable import RunPlayPlatform

/// Reading a synthetic `export.zip` into a scan and candidates.
///
/// Every archive here is built in a temporary directory from generated bytes —
/// except the two checked-in `Fixtures/apple-health-zip64-descriptors*.zip`, which
/// are generated from invented content by the script beside them. Both are
/// synthetic: nothing is read from the developer's machine.
final class AppleHealthArchiveServiceTests: XCTestCase {

    private var tempDir: URL!

    /// A private extraction root under the test's own directory, so no test ever
    /// writes into the real app caches directory.
    private var extractionRoot: URL {
        tempDir.appendingPathComponent("extractions", isDirectory: true)
    }

    override func setUp() {
        super.setUp()
        tempDir = FileManager.default.temporaryDirectory
            .appendingPathComponent("AppleHealthArchive-\(UUID().uuidString)")
        try? FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
    }

    override func tearDown() {
        try? FileManager.default.removeItem(at: tempDir)
        super.tearDown()
    }

    /// A service pointed at the test's private extraction directory.
    ///
    /// `availableCapacity` defaults to `nil`, which disables the free-space
    /// check; a test that exercises it passes a byte count.
    private func makeService(
        policy: WorkoutArchiveSecurityPolicy = .default,
        staleExtractionAge: TimeInterval = 3_600,
        availableCapacity: Int64? = nil,
        sourcePayloadByteLimit: Int64 = Int64(WorkoutImportResourceLimits.maxSourceFileBytes)
    ) -> AppleHealthArchiveService {
        AppleHealthArchiveService(
            policy: policy,
            extractionRoot: extractionRoot,
            staleExtractionAge: staleExtractionAge,
            availableCapacity: { _ in availableCapacity },
            sourcePayloadByteLimit: sourcePayloadByteLimit
        )
    }

    // MARK: - Synthetic fixtures

    private func writeArchive(
        named: String,
        entries: [(path: String, type: Entry.EntryType, data: Data)],
        compression: CompressionMethod = .none
    ) throws -> URL {
        let url = tempDir.appendingPathComponent(named)
        if FileManager.default.fileExists(atPath: url.path) {
            try FileManager.default.removeItem(at: url)
        }
        let archive = try Archive(url: url, accessMode: .create)
        for entry in entries {
            try archive.addEntry(
                with: entry.path,
                type: entry.type,
                uncompressedSize: Int64(entry.data.count),
                compressionMethod: compression,
                provider: { position, size in
                    let start = Int(position)
                    let end = min(start + size, entry.data.count)
                    return entry.data.subdata(in: start..<end)
                }
            )
        }
        return url
    }

    private func writeZip(named: String, entries: [(path: String, data: Data)]) throws -> URL {
        try writeArchive(named: named, entries: entries.map { ($0.path, .file, $0.data) })
    }

    private func healthDocument(records: String = "", workouts: String = "") -> Data {
        let xml = """
        <?xml version="1.0" encoding="UTF-8"?>
        <HealthData locale="en_US">
        \(records)
        \(workouts)
        </HealthData>
        """
        return Data(xml.utf8)
    }

    private func runningWorkout(
        _ start: String = "2026-09-01 08:00:00 +0000",
        _ end: String = "2026-09-01 09:00:00 +0000",
        route: String? = nil
    ) -> String {
        let body = route.map { "<WorkoutRoute><FileReference path=\"\($0)\"/></WorkoutRoute>" } ?? ""
        return "<Workout workoutActivityType=\"HKWorkoutActivityTypeRunning\" "
            + "startDate=\"\(start)\" endDate=\"\(end)\">\(body)</Workout>"
    }

    private func heartRateRecord(value: Int, at instant: String = "2026-09-01 08:30:00 +0000") -> String {
        "<Record type=\"HKQuantityTypeIdentifierHeartRate\" value=\"\(value)\" "
            + "startDate=\"\(instant)\" endDate=\"\(instant)\"/>"
    }

    private func routeGPX() -> Data {
        Data("""
        <?xml version="1.0" encoding="UTF-8"?>
        <gpx version="1.1" creator="RunPlayTest"><trk><trkseg>
        <trkpt lat="37.77" lon="-122.42"><ele>10</ele></trkpt>
        <trkpt lat="37.78" lon="-122.42"><ele>12</ele></trkpt>
        </trkseg></trk></gpx>
        """.utf8)
    }

    private static let exportPath = "apple_health_export/export.xml"
    private static let routePath = "apple_health_export/workout-routes/route_1.gpx"

    // MARK: - Extraction leftovers

    private func extractionFileNames() -> [String] {
        let names = (try? FileManager.default.contentsOfDirectory(atPath: extractionRoot.path)) ?? []
        return names.filter { $0.hasPrefix("runplay-health-extraction-") }.sorted()
    }

    // MARK: - Helpers

    private func assertThrows(
        _ expected: AppleHealthArchiveError,
        file: StaticString = #filePath,
        line: UInt = #line,
        _ operation: () async throws -> Void
    ) async {
        do {
            try await operation()
            XCTFail("expected \(expected)", file: file, line: line)
        } catch let error as AppleHealthArchiveError {
            XCTAssertEqual(error, expected, file: file, line: line)
        } catch {
            XCTFail("expected \(expected), got \(error)", file: file, line: line)
        }
    }

    private func assertFails(
        file: StaticString = #filePath,
        line: UInt = #line,
        _ operation: () async throws -> Void
    ) async {
        do {
            try await operation()
            XCTFail("expected the operation to fail", file: file, line: line)
        } catch {
            // Any error is acceptable here; the caller asserts the residue.
        }
    }

    private func assertCancels(
        file: StaticString = #filePath,
        line: UInt = #line,
        _ operation: () async throws -> Void
    ) async {
        do {
            try await operation()
            XCTFail("expected CancellationError", file: file, line: line)
        } catch is CancellationError {
            // expected
        } catch {
            XCTFail("expected CancellationError, got \(error)", file: file, line: line)
        }
    }

    // MARK: - The happy path

    func testSyntheticExportIsScannedIntoCandidates() async throws {
        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(workouts: runningWorkout(route: "/workout-routes/route_1.gpx"))),
            (Self.routePath, routeGPX()),
        ])

        let result = try await makeService().scan(archiveAt: url)

        XCTAssertEqual(result.exportXMLEntryPath, Self.exportPath)
        XCTAssertFalse(result.usedCaseInsensitiveXMLLookup)
        XCTAssertEqual(result.report.entryCount, 2)
        XCTAssertEqual(result.report.routeEntryCount, 1)
        XCTAssertEqual(result.report.unmatchedRouteReferenceCount, 0)
        XCTAssertEqual(result.report.droppedWorkoutCount, 0)
        XCTAssertGreaterThan(result.report.uncompressedXMLBytes, 0)

        XCTAssertEqual(result.scan.workouts.count, 1)
        XCTAssertEqual(result.candidates.count, 1)
        let candidate = try XCTUnwrap(result.candidates.first)
        XCTAssertEqual(candidate.routeArchivePath, Self.routePath)
        XCTAssertTrue(candidate.hasRoute)
        XCTAssertEqual(candidate.distanceProvenance, .gpsDerived)
        XCTAssertEqual(candidate.status, .ready)
    }

    func testRouteLessWorkoutCarriesNoRouteAndReportsSourceDistance() async throws {
        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(workouts: runningWorkout())),
        ])

        let result = try await makeService().scan(archiveAt: url)

        let candidate = try XCTUnwrap(result.candidates.first)
        XCTAssertNil(candidate.routeArchivePath)
        XCTAssertFalse(candidate.hasRoute)
        XCTAssertEqual(candidate.distanceProvenance, .sourceReported)
        XCTAssertEqual(result.report.routeEntryCount, 0)
    }

    /// A referenced route the archive does not hold is counted, not resolved away.
    func testRouteReferenceWithNoMatchingEntryIsCounted() async throws {
        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(workouts: runningWorkout(route: "/workout-routes/route_1.gpx"))),
        ])

        let result = try await makeService().scan(archiveAt: url)

        XCTAssertEqual(result.report.routeEntryCount, 0)
        XCTAssertEqual(result.report.unmatchedRouteReferenceCount, 1)
    }

    /// The import report carries both loss counts together, which is what a
    /// review screen shows after an import finishes.
    func testReportCarriesDroppedWorkoutsAlongsideUnmatchedRoutes() async throws {
        let unreadable = "<Workout workoutActivityType=\"HKWorkoutActivityTypeRunning\" "
            + "startDate=\"not-a-date\" endDate=\"also-not-a-date\"/>"
        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(
                workouts: unreadable + runningWorkout(route: "/workout-routes/missing.gpx")
            )),
        ])

        let result = try await makeService().scan(archiveAt: url)

        XCTAssertEqual(result.report.droppedWorkoutCount, 1)
        XCTAssertEqual(result.report.unmatchedRouteReferenceCount, 1)
        XCTAssertEqual(result.report.candidateCount, 1)
    }

    func testHeartRateInsideTheWindowReachesTheCandidate() async throws {
        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(
                records: heartRateRecord(value: 152),
                workouts: runningWorkout()
            )),
        ])

        let result = try await makeService().scan(archiveAt: url)

        let candidate = try XCTUnwrap(result.candidates.first)
        XCTAssertEqual(candidate.heartRate.map(\.beatsPerMinute), [152])
    }

    /// Duplicate flagging reaches the candidates without a second heart-rate path.
    func testOverlappingWorkoutsAreFlaggedAsPossibleDuplicates() async throws {
        let first = runningWorkout("2026-09-01 08:00:00 +0000", "2026-09-01 09:00:00 +0000")
        let second = runningWorkout("2026-09-01 08:30:00 +0000", "2026-09-01 09:30:00 +0000")
        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(workouts: first + second)),
        ])

        let result = try await makeService().scan(archiveAt: url)

        XCTAssertEqual(result.candidates.map(\.status), [.possibleDuplicate, .possibleDuplicate])
        XCTAssertTrue(result.candidates.allSatisfy { !$0.isSelectedByDefault })
        XCTAssertEqual(result.report.duplicateCandidateCount, 2)
    }

    /// Whole seconds since the epoch for a UTC instant, computed independently of
    /// the parser's own date handling.
    private func utcSeconds(
        _ year: Int, _ month: Int, _ day: Int, _ hour: Int, _ minute: Int = 0
    ) -> Int64 {
        var components = DateComponents()
        components.year = year
        components.month = month
        components.day = day
        components.hour = hour
        components.minute = minute
        components.timeZone = TimeZone(secondsFromGMT: 0)
        guard let date = Calendar(identifier: .gregorian).date(from: components) else {
            XCTFail("could not build a UTC date for \(year)-\(month)-\(day) \(hour):\(minute)")
            return 0
        }
        return Int64(date.timeIntervalSince1970)
    }

    func testExistingLibraryRunFlagsTheCandidateItOverlaps() async throws {
        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(workouts: runningWorkout())),
        ])
        // The workout runs 2026-09-01 08:00:00–09:00:00 UTC.
        let start = utcSeconds(2026, 9, 1, 8)
        let library = [AppleHealthLibraryRunWindow(startSeconds: start, endSeconds: start + 3_600)]

        let result = try await makeService().scan(
            archiveAt: url,
            existingLibraryRuns: library
        )

        XCTAssertEqual(result.candidates.map(\.status), [.duplicate])
    }

