    // MARK: - Extraction hardening

    /// Extraction lands in a private directory this app owns, not the shared
    /// temporary directory, and both directory and file are owner-only.
    func testExtractionUsesAPrivateDirectoryAndOwnerOnlyPermissions() async throws {
        let defaultDirectory = AppleHealthArchiveService.defaultExtractionDirectory()
        XCTAssertTrue(
            defaultDirectory.path.hasSuffix("RunPlayStudio/AppleHealthExtractions"),
            "expected an app-owned subdirectory, got \(defaultDirectory.path)"
        )
        XCTAssertFalse(
            defaultDirectory.path.hasPrefix(FileManager.default.temporaryDirectory.path),
            "extraction must not share the temporary directory root"
        )

        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(workouts: runningWorkout())),
            (Self.routePath, routeGPX()),
        ])
        let probe = ExtractionProbe(directory: extractionRoot)

        _ = try await makeService().scan(archiveAt: url, isCancelled: probe.predicate)

        // The file is gone by now, so the mode was captured while it existed.
        XCTAssertEqual(probe.filePermissions, 0o600, "the extraction file must be owner-only")

        let directoryAttributes = try FileManager.default.attributesOfItem(atPath: extractionRoot.path)
        let directoryPermissions = (directoryAttributes[.posixPermissions] as? NSNumber)?.intValue
        XCTAssertEqual(directoryPermissions, 0o700, "the extraction directory must be owner-only")
    }

    /// A parse failure still removes the extracted document.
    func testExtractionFileIsRemovedWhenParsingThrows() async throws {
        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, Data("<HealthData><Workout".utf8)),
        ])

        await assertFails {
            _ = try await makeService().scan(archiveAt: url)
        }
        XCTAssertTrue(extractionFileNames().isEmpty, "a failed parse must leave no extraction file")
    }

    /// The descriptor retains the real size: Entry.uncompressedSize therefore
    /// cannot detect this mismatch. The service must consult the central directory.
    func testUnderstatedCentralDirectorySizeAbortsAndRemovesExtraction() async throws {
        let document = healthDocument(records: "<!-- " + String(repeating: "x", count: 200_000) + " -->")
        let url = try writeArchive(
            named: "understated.zip", entries: [(Self.exportPath, .file, document)], compression: .deflate
        )
        var bytes = try Data(contentsOf: url)
        let central = try XCTUnwrap(bytes.range(of: Data([0x50, 0x4b, 0x01, 0x02]))).lowerBound
        let descriptor = Data([0x50, 0x4b, 0x07, 0x08]) + bytes.subdata(in: (central + 16)..<(central + 28))
        bytes[6] |= 8 // Local header: use a data descriptor.
        bytes.insert(contentsOf: descriptor, at: central)
        let newCentral = central + descriptor.count
        bytes[newCentral + 8] |= 8
        let declared = UInt32(document.count - 1)
        for index in 0..<4 {
            bytes[newCentral + 24 + index] = UInt8(truncatingIfNeeded: declared >> (index * 8))
            bytes[bytes.count - 22 + 16 + index] = UInt8(truncatingIfNeeded: UInt32(newCentral) >> (index * 8))
        }
        try bytes.write(to: url)
        let archive = try Archive(url: url, accessMode: .read)
        XCTAssertEqual(try XCTUnwrap(archive.first { _ in true }).uncompressedSize, UInt64(document.count))
        let probe = ExtractionProbe(directory: extractionRoot)
        await assertThrows(.entryExceedsDeclaredSize(path: Self.exportPath, declaredBytes: UInt64(declared))) {
            _ = try await self.makeService().scan(archiveAt: url, isCancelled: probe.predicate)
        }
        XCTAssertEqual(probe.filePermissions, 0o600, "must abort a real partial extraction")
        XCTAssertTrue(extractionFileNames().isEmpty)
    }

    /// Cancelling partway through extraction removes the half-written file and
    /// returns nothing.
    func testCancellationDuringExtractionLeavesNoExtractionFile() async throws {
        // Larger than one 64 KiB chunk, so extraction is still running when the
        // predicate first says to stop.
        let filler = String(repeating: "x", count: 200_000)
        let document = healthDocument(
            records: "<!-- \(filler) -->",
            workouts: runningWorkout()
        )
        let url = try writeZip(named: "export.zip", entries: [(Self.exportPath, document)])

        // Calls: 1 is the check after listing, 2 and 3 are the first two
        // extraction chunks. Stopping at 3 cancels mid-extraction.
        let counter = CallCounter(cancelAt: 3)
        await assertCancels {
            _ = try await makeService().scan(archiveAt: url, isCancelled: counter.predicate)
        }
        XCTAssertGreaterThanOrEqual(counter.callCount, 3)
        XCTAssertTrue(extractionFileNames().isEmpty)
    }

    /// A crash skips `defer`, so the next import sweeps the orphan it left.
    func testStaleExtractionFileFromAPreviousCrashIsSwept() async throws {
        let staleURL = extractionRoot.appendingPathComponent("runplay-health-extraction-stale.xml")
        try FileManager.default.createDirectory(at: extractionRoot, withIntermediateDirectories: true)
        try Data("<HealthData/>".utf8).write(to: staleURL)
        // Backdate it so it is unambiguously older than the threshold.
        try FileManager.default.setAttributes(
            [.modificationDate: Date().addingTimeInterval(-7_200)],
            ofItemAtPath: staleURL.path
        )

        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(workouts: runningWorkout())),
        ])
        _ = try await makeService().scan(archiveAt: url)

        XCTAssertFalse(
            FileManager.default.fileExists(atPath: staleURL.path),
            "a stale extraction file must be swept on the next import"
        )
    }

    /// The sweep is age-gated, so it cannot delete the live file of an import
    /// running in another copy of the app.
    func testFreshExtractionFileIsNotSwept() async throws {
        let freshURL = extractionRoot.appendingPathComponent("runplay-health-extraction-fresh.xml")
        try FileManager.default.createDirectory(at: extractionRoot, withIntermediateDirectories: true)
        try Data("<HealthData/>".utf8).write(to: freshURL)

        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(workouts: runningWorkout())),
        ])
        _ = try await makeService().scan(archiveAt: url)

        XCTAssertTrue(
            FileManager.default.fileExists(atPath: freshURL.path),
            "a recent extraction file is not stale and must be left alone"
        )
    }

    /// Too little free space is a clear refusal, not a partial file.
    func testInsufficientFreeSpaceIsRefusedBeforeExtracting() async throws {
        let document = healthDocument(workouts: runningWorkout())
        let url = try writeZip(named: "export.zip", entries: [(Self.exportPath, document)])

        await assertThrows(
            .insufficientFreeSpace(requiredBytes: Int64(document.count), availableBytes: 1)
        ) {
            _ = try await makeService(availableCapacity: 1).scan(archiveAt: url)
        }
        XCTAssertTrue(extractionFileNames().isEmpty)
    }

