    /// An absolute path is refused rather than trimmed into a relative one.
    func testAbsoluteRoutePathIsRefused() async throws {
        let url = try writeZip(named: "export.zip", entries: [
            (Self.exportPath, healthDocument(workouts: runningWorkout())),
            (Self.routePath, routeGPX()),
        ])

        await assertThrows(
            .routePathRejected(path: "/\(Self.routePath)", reason: .absolute)
        ) {
            _ = try await makeService().routeGPXData(
                forArchivePath: "/\(Self.routePath)",
                archiveAt: url
            )
        }
    }

    /// A parent-directory segment is refused, even though resolving it would land
