    // MARK: - Archive format coverage

    /// The checked-in fixture carries a ZIP64 end-of-central-directory record and
    /// uses a data descriptor for its entry. Both features must import the same
    /// way the equivalent plain archive does.
    ///
    /// The fixture is regenerated by
    /// `Fixtures/make_zip64_descriptor_fixture.py`; its doc comment records why a
    /// hand-rolled generator was needed and what limits were verified.
    func testZip64ArchiveWithDataDescriptorsImportsLikeAPlainArchive() async throws {
        let fixtureURL = try XCTUnwrap(
            Bundle.module.url(
                forResource: "apple-health-zip64-descriptors",
                withExtension: "zip",
                subdirectory: "Fixtures"
            ),
            "the generated ZIP64 fixture is missing from the test bundle"
        )

        // The fixture must genuinely use both features, or the comparison proves
        // nothing about them.
        let bytes = try Data(contentsOf: fixtureURL)
        XCTAssertNotNil(
            bytes.range(of: Data([0x50, 0x4B, 0x06, 0x06])),
            "expected a ZIP64 end-of-central-directory record"
        )
        XCTAssertNotNil(
            bytes.range(of: Data([0x50, 0x4B, 0x06, 0x07])),
            "expected a ZIP64 end-of-central-directory locator"
        )
        let localHeader = try XCTUnwrap(bytes.range(of: Data([0x50, 0x4B, 0x03, 0x04])))
        let firstByte = bytes.startIndex + localHeader.lowerBound
        let flags = UInt16(bytes[firstByte + 6]) | (UInt16(bytes[firstByte + 7]) << 8)
        XCTAssertEqual(flags & 0x0008, 0x0008, "expected the data-descriptor flag")

        let plainURL = try writeZip(named: "plain.zip", entries: [
            (Self.exportPath, healthDocument(
                records: heartRateRecord(value: 141),
                workouts: runningWorkout()
            )),
        ])

        let service = makeService()
        let zip64 = try await service.scan(archiveAt: fixtureURL)
        let plain = try await service.scan(archiveAt: plainURL)

        XCTAssertEqual(zip64.candidates.count, 1)
        XCTAssertEqual(zip64.candidates.map(\.status), plain.candidates.map(\.status))
        XCTAssertEqual(zip64.candidates.map(\.window), plain.candidates.map(\.window))
        XCTAssertEqual(
            zip64.candidates.map { $0.heartRate.map(\.beatsPerMinute) },
            plain.candidates.map { $0.heartRate.map(\.beatsPerMinute) }
        )
        XCTAssertEqual(zip64.candidates.map(\.distanceProvenance), plain.candidates.map(\.distanceProvenance))
        XCTAssertEqual(zip64.report.workoutCount, plain.report.workoutCount)
        XCTAssertEqual(zip64.report.droppedWorkoutCount, plain.report.droppedWorkoutCount)
        XCTAssertEqual(zip64.report.routeEntryCount, plain.report.routeEntryCount)
        XCTAssertEqual(zip64.report.unmatchedRouteReferenceCount, plain.report.unmatchedRouteReferenceCount)
    }

    /// Pins a ZIPFoundation 0.9.20 defect, and the refusal it forces on us.
    ///
    /// `Fixtures/apple-health-zip64-descriptors-offset-sentinel.zip` is the same
    /// synthetic export as the fixture above, written the other way a ZIP64
    /// archive may legitimately express an entry's local-header offset: the real
    /// offset (0, because the entry starts the file) sits in the ZIP64 extra
    /// field, and the central directory's 32-bit slot holds the sentinel
    /// `0xFFFFFFFF`. `unzip` and Python's `zipfile` both read the entry out of it.
    ///
    /// ZIPFoundation 0.9.20 does not. `Entry.CentralDirectoryStructure
    /// .effectiveRelativeOffsetOfLocalHeader` (`Entry.swift:311`) consults the
    /// extra field only when the offset it holds is *greater than zero*, so this
    /// entry's real offset of 0 is discarded in favour of the sentinel.
    /// `Archive.makeIterator` (`Archive.swift:229`) then fails to read a local
    /// file header at that position and ends the sequence early, and the archive
    /// reports **zero entries** despite holding one.
    ///
    /// This test exists so that a silent zero-entry listing cannot pass as an
    /// empty archive, and so that the eventual dependency bump has a tripwire: it
    /// reaches ZIPFoundation directly and asserts the zero-entry listing, so
    /// fixing the library fails this test rather than quietly changing behaviour.
    /// When that happens, this fixture should import like the plain archive above
    /// and both assertions below should be replaced by the comparison.
    ///
    /// Known gap, deliberately left as-is rather than papered over: because the
    /// listing is empty, the scan refuses with `exportXMLNotFound`, whose message
    /// says the ZIP holds no export document. That message is *wrong* for this
    /// archive — the document is in it — so a real export in this layout would
    /// report a misleading reason.
    func testZip64OffsetSentinelArchiveIsRefusedBecauseZIPFoundationListsNoEntries() async throws {
        let fixtureURL = try XCTUnwrap(
            Bundle.module.url(
                forResource: "apple-health-zip64-descriptors-offset-sentinel",
                withExtension: "zip",
                subdirectory: "Fixtures"
            ),
            "the generated ZIP64 offset-sentinel fixture is missing from the test bundle"
        )

        let bytes = try Data(contentsOf: fixtureURL)

        // The archive itself is well formed. Asserting this here keeps the claim
        // precise: a failure below is the library's listing, not a broken fixture.
        XCTAssertNotNil(
            bytes.range(of: Data([0x50, 0x4B, 0x06, 0x06])),
            "expected a ZIP64 end-of-central-directory record"
        )
        XCTAssertNotNil(
            bytes.range(of: Data([0x50, 0x4B, 0x06, 0x07])),
            "expected a ZIP64 end-of-central-directory locator"
        )
        XCTAssertNotNil(
            bytes.range(of: Data(Self.exportPath.utf8)),
            "expected the export entry's name in the archive"
        )
        XCTAssertNotNil(
            bytes.range(of: Data([0x50, 0x4B, 0x03, 0x04])),
            "expected the export entry's local file header"
        )

        // The defect, stated as the library's own observable behaviour.
        let archive = try Archive(url: fixtureURL, accessMode: .read)
        XCTAssertEqual(
            Array(archive).count,
            0,
            "ZIPFoundation listed entries for an entry whose ZIP64 local-header offset is 0. "
                + "If this reached 0.9.21 or later, the library fixed Entry.swift:311 — replace this "
                + "assertion and the refusal below with the plain-archive comparison used above."
        )

        // What the caller sees. A refusal, not a crash and not an empty import.
        do {
            _ = try await makeService().scan(archiveAt: fixtureURL)
            XCTFail("expected the scan to refuse an archive whose sole entry cannot be listed")
        } catch let error as AppleHealthArchiveError {
            XCTAssertEqual(
                error,
                .exportXMLNotFound,
                "the scan must surface the unreadable listing as its existing refusal"
            )
        }
    }

    // MARK: - Cancellation

