    }
}

/// A cancellation predicate that counts calls, records the extraction file's mode
/// while it exists, and can start cancelling at a chosen call.
private final class ExtractionProbe: @unchecked Sendable {
    private let lock = NSLock()
    private let directory: URL
    private var calls = 0
    private var observedPermissions: Int?
    private let cancelAt: Int

    init(directory: URL, cancelAt: Int = Int.max) {
        self.directory = directory
        self.cancelAt = cancelAt
    }

    var predicate: @Sendable () -> Bool {
        { [self] in
            lock.lock()
            defer { lock.unlock() }
            calls += 1
            captureFilePermissions()
            return calls >= cancelAt
        }
    }

    /// The extraction file's POSIX permissions, read while the file still exists.
    var filePermissions: Int? {
        lock.lock()
        defer { lock.unlock() }
        return observedPermissions
    }

    private func captureFilePermissions() {
        guard observedPermissions == nil else { return }
        let manager = FileManager.default
        guard let names = try? manager.contentsOfDirectory(atPath: directory.path) else { return }
        for name in names where name.hasPrefix("runplay-health-extraction-") {
            let path = directory.appendingPathComponent(name).path
            guard let attributes = try? manager.attributesOfItem(atPath: path) else { continue }
            observedPermissions = (attributes[.posixPermissions] as? NSNumber)?.intValue
            return
        }
    }
}

/// A cancellation predicate that counts calls and starts cancelling at a point.
private final class CallCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var calls = 0
    private let cancelAt: Int

    init(cancelAt: Int) {
        self.cancelAt = cancelAt
    }

    var callCount: Int {
        lock.lock()
        defer { lock.unlock() }
        return calls
    }

    var predicate: @Sendable () -> Bool {
        { [self] in
            lock.lock()
            defer { lock.unlock() }
            calls += 1
            return calls >= cancelAt
        }
    }
}
